    'researchScope.changeIdentity': { fr: 'Changer d’identité', en: 'Change identity' },
    'researchScope.noticeSummary': { fr: 'Données personnelles professionnelles · OpenAlex · cache 15 min', en: 'Professional personal data · OpenAlex · 15-minute cache' },
    'researchScope.noticeBody': { fr: 'Cette fonction traite, à votre demande, des métadonnées bibliographiques publiques pouvant identifier une personne : nom, ORCID, affiliations, publications et citations. Elles proviennent d’OpenAlex et servent uniquement à identifier l’auteur ou l’institution sélectionnée puis à construire la cartographie demandée. Bibliobrain ne crée aucun profil permanent ni décision automatisée.', en: 'At your request, this feature processes public bibliographic metadata that may identify a person: name, ORCID, affiliations, publications, and citations. It comes from OpenAlex and is used only to identify the selected author or institution and build the requested map. Bibliobrain creates no permanent profile or automated decision.' },
    'researchScope.noticeResponsibility': { fr: 'Le responsable du traitement est la personne ou l’organisme qui utilise Bibliobrain et détermine l’objectif de la cartographie. Il lui appartient de définir et documenter la base légale appropriée, de fournir ses coordonnées dans ses mentions d’information et de permettre l’exercice des droits des personnes.', en: 'The data controller is the person or organization using Bibliobrain and determining the purpose of the map. They must define and document the appropriate legal basis, provide their contact details in their privacy information, and enable data subjects to exercise their rights.' },
    'researchScope.noticeRetention': { fr: 'Pour effectuer la recherche, le nom ou l’identifiant, le type d’entité et les filtres choisis sont transmis à l’API OpenAlex, qui traite aussi les métadonnées techniques de la requête selon sa propre politique. La saisie est envoyée au serveur Bibliobrain dans le corps d’une requête POST : elle n’est pas inscrite dans les journaux d’accès standards de l’application. Les réponses sont traitées sur cet appareil et peuvent rester dans un cache mémoire temporaire de 15 minutes, supprimé à l’arrêt. Aucun historique nominatif n’est enregistré par Bibliobrain.', en: 'To perform the search, the name or identifier, entity type, and selected filters are sent to the OpenAlex API, which also processes technical request metadata under its own policy. The input is sent to the Bibliobrain server in a POST request body, so it is not written to the application’s standard access logs. Responses are processed on this device and may remain in a temporary 15-minute memory cache that is deleted on shutdown. Bibliobrain stores no named search history.' },
    'researchScope.openAlexLink': { fr: 'Source : OpenAlex', en: 'Source: OpenAlex' },
    'researchScope.openAlexPrivacyLink': { fr: 'Confidentialité OpenAlex', en: 'OpenAlex privacy' },
    'researchScope.rightsLink': { fr: 'Information et droits (CNIL)', en: 'Information and rights (CNIL)' },
